import sys,collections,heapq,itertools,functools,bisect
def solve(data):
    v=data.split();n=int(v[0]);a=[sum(1<<j for j,c in enumerate(s) if c==".") for s in v[1:]];mask=(1<<n)-1
    def f(i,c,l,r):
        if i==n:return 1
        v=a[i]&~(c|l|r);ans=0
        while v:
            x=v&-v;v-=x;ans+=f(i+1,c|x,((l|x)<<1)&mask,(r|x)>>1)
        return ans
    return f(0,0,0,0)

if __name__=="__main__":
    a=solve(sys.stdin.buffer.read().decode())
    print(" ".join(map(str,a)) if isinstance(a,(list,tuple)) else a)
